class Solution {
public:
    bool winnerOfGame(string colors) {
        int a = 0, b = 0;
        int n = (int)colors.size();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && colors[j] == colors[i]) j++;
            int len = j - i;
            if (colors[i] == 'A') a += (len > 2 ? len - 2 : 0);
            else b += (len > 2 ? len - 2 : 0);
            i = j;
        }
        return a > b;
    }
};
